async function expectPillAction(button:Locator){
  const geometry=await button.evaluate(element=>({radius:parseFloat(getComputedStyle(element).borderTopLeftRadius),height:element.getBoundingClientRect().height,touch:matchMedia('(pointer:coarse), (max-width:700px)').matches}));
  expect(geometry.radius).toBeGreaterThanOrEqual(geometry.height/2);
  if(geometry.touch)expect(geometry.height).toBeGreaterThanOrEqual(44);
}
