async function getDeclaredTargetGlow(page:Page){
  return page.evaluate(()=>{
    const findRule=(rules:CSSRuleList):{animation:string}|null=>{
      for(const rule of Array.from(rules)){
        if(rule.type===CSSRule.STYLE_RULE){
          const styleRule=rule as CSSStyleRule;
          if(styleRule.selectorText.includes('.asset-note-active-issue-card.is-deep-link-target::after')&&styleRule.style.animation.includes('asset-note-target-glow-pulse'))return{animation:styleRule.style.animation};
        }
        const nestedRules=(rule as CSSMediaRule).cssRules;
        if(nestedRules){const match=findRule(nestedRules);if(match)return match;}
      }
      return null;
    };
    for(const sheet of Array.from(document.styleSheets)){try{const match=findRule(sheet.cssRules);if(match)return match;}catch{/* Cross-origin stylesheets are irrelevant to the application rule. */}}
    return null;
  });
}

function getRuntimeTargetHighlight(target:Locator,minimumOpacity:number){
  return target.evaluate((element,opacityFloor)=>{
    const card=getComputedStyle(element);const glow=getComputedStyle(element,'::after');const visibleColor=(color:string)=>color!=='transparent'&&color!=='rgba(0, 0, 0, 0)';
    return{highlighted:element.classList.contains('is-deep-link-target'),animation:glow.animationName,background:glow.backgroundImage,transform:glow.transform,outlineStyle:card.outlineStyle,outlineWidth:card.outlineWidth,outlineColorVisible:visibleColor(card.outlineColor),cardBorderStyle:card.borderTopStyle,cardBorderWidth:card.borderTopWidth,cardBorderColorVisible:visibleColor(card.borderTopColor),cardGlowPresent:card.boxShadow!=='none',glowBorderStyle:glow.borderTopStyle,glowBorderWidth:glow.borderTopWidth,glowBorderColorVisible:visibleColor(glow.borderTopColor),glowOpacityPresent:Number(glow.opacity)>=opacityFloor,glowShadowPresent:glow.boxShadow!=='none'};
  },minimumOpacity);
}

